mapper.select:
SELECT t.dept_id, t.dept_name, t.school_type, COUNT(DISTINCT CONCAT(t.entry_year, '-', t.class_code)) AS class_count, COUNT(DISTINCT t.student_id) AS active_student_count, ROUND(SUM(t.typing_speed_sum) / NULLIF(SUM(t.typing_speed_count), 0), 0) AS avg_typing_speed, ROUND(AVG(t.lesson_total_score), 1) AS avg_total_score, ROUND(SUM(CASE WHEN t.lesson_total_score >= 60 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 1) AS pass_rate, ROUND(SUM(CASE WHEN t.lesson_total_score >= 90 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 1) AS excellent_rate FROM ( SELECT a.student_id, a.lesson_id, u.dept_id, d.dept_name, d.school_type, s.entry_year, s.class_code, SUM(CASE WHEN a.typing_speed > 0 THEN a.typing_speed ELSE 0 END) AS typing_speed_sum, COUNT(CASE WHEN a.typing_speed > 0 THEN 1 END) AS typing_speed_count, SUM(a.score) AS lesson_total_score FROM biz_student_answer a INNER JOIN biz_lesson l ON a.lesson_id = l.lesson_id INNER JOIN biz_question q ON q.question_id = a.question_id INNER JOIN biz_student s ON a.student_id = s.student_id INNER JOIN sys_user u ON s.user_id = u.user_id INNER JOIN sys_dept d ON u.dept_id = d.dept_id WHERE d.del_flag = '0' AND d.parent_id != 0 AND a.submit_time >= #{startDate} AND a.submit_time < #{endDate}
AND s.entry_year = #{entryYear} AND d.school_type = #{schoolType}
AND d.dept_name like concat('%', #{deptName}, '%')
GROUP BY a.student_id, a.lesson_id, u.dept_id, d.dept_name, d.school_type, s.entry_year, s.class_code HAVING SUM(CASE WHEN q.question_type = 'practical' AND a.score IS NULL THEN 1 ELSE 0 END) = 0 ) t GROUP BY t.dept_id, t.dept_name, t.school_type ORDER BY avg_typing_speed DESC

SELECT t.dept_id,
CONCAT(t.entry_year, '级', t.class_code, '班') AS dept_name, t.school_type, 1 AS class_count, COUNT(DISTINCT t.student_id) AS active_student_count, ROUND(SUM(t.typing_speed_sum) / NULLIF(SUM(t.typing_speed_count), 0), 0) AS avg_typing_speed, ROUND(AVG(t.lesson_total_score), 1) AS avg_total_score, ROUND(SUM(CASE WHEN t.lesson_total_score >= 60 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 1) AS pass_rate, ROUND(SUM(CASE WHEN t.lesson_total_score >= 90 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 1) AS excellent_rate FROM ( SELECT a.student_id, a.lesson_id, u.dept_id, d.school_type, s.entry_year, s.class_code, SUM(CASE WHEN a.typing_speed > 0 THEN a.typing_speed ELSE 0 END) AS typing_speed_sum, COUNT(CASE WHEN a.typing_speed > 0 THEN 1 END) AS typing_speed_count, SUM(a.score) AS lesson_total_score FROM biz_student_answer a INNER JOIN biz_lesson l ON a.lesson_id = l.lesson_id INNER JOIN biz_question q ON q.question_id = a.question_id INNER JOIN biz_student s ON a.student_id = s.student_id INNER JOIN sys_user u ON s.user_id = u.user_id INNER JOIN sys_dept d ON u.dept_id = d.dept_id WHERE u.dept_id = #{deptId} AND a.submit_time >= #{startDate} AND a.submit_time < #{endDate}
AND s.entry_year = #{entryYear} AND d.school_type = #{schoolType}
GROUP BY a.student_id, a.lesson_id, u.dept_id, d.school_type, s.entry_year, s.class_code HAVING SUM(CASE WHEN q.question_type = 'practical' AND a.score IS NULL THEN 1 ELSE 0 END) = 0 ) t GROUP BY t.dept_id, t.school_type, t.entry_year, t.class_code ORDER BY t.entry_year DESC, t.class_code ASC
